package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.math.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class PerfSummaryProvider extends AbstractLabDataSourceProvider { private static final String PERMISSION="lab:report:sensitive"; public PerfSummaryProvider(){super(ReportConfigCatalog.PERF_SUMMARY,new LinkedHashSet<String>(Arrays.asList("period","memberId","resultStatus","score","revisionNo","redLineFlag","confirmationStatus")));} @Override protected boolean supports(ReportPeriod.Kind kind){return kind==ReportPeriod.Kind.MONTH||kind==ReportPeriod.Kind.QUARTER;} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){if(!c.getScope().hasPermission(PERMISSION))throw new SecurityException("Missing report sensitive permission");List<Map<String,Object>>r=copyRows(mapper().selectCurrentPerfScores(c));Map<String,Object>z=summaryCount(r);recomputeFilteredSummary(r,z);return section(c,s,r,z);} @Override protected void recomputeFilteredSummary(List<Map<String,Object>> rows,Map<String,Object> summary){BigDecimal total=BigDecimal.ZERO;for(Map<String,Object>x:rows)total=total.add(number(x.get("score")));summary.put("averageScore",rows.isEmpty()?BigDecimal.ZERO:total.divide(BigDecimal.valueOf(rows.size()),2,RoundingMode.HALF_UP));}}
